mapper.update:
UPDATE TB_COMM_CODE_GROUP
   SET GROUP_NM = #{r.groupNm}
     , USE_YN   = COALESCE(#{r.useYn,jdbcType=VARCHAR}, 'Y')
     , MOD_ID   = #{loginId}
     , MOD_DT   = CURRENT_TIMESTAMP
 WHERE GROUP_CD = #{r.groupCd}

UPDATE TB_COMM_CODE
   SET CODE_NM  = #{r.codeNm}
     , SORT_ORD = COALESCE(CAST(#{r.sortOrd,jdbcType=VARCHAR} AS INTEGER), 0)
     , USE_YN   = COALESCE(#{r.useYn,jdbcType=VARCHAR}, 'Y')
     , MOD_ID   = #{loginId}
     , MOD_DT   = CURRENT_TIMESTAMP
 WHERE GROUP_CD = #{r.groupCd}
   AND CODE     = #{r.code}
